(function(){
const $id=id=>document.getElementById(id),player=$id('quran-audio');
if(!player)return;
const folders={'ar.alafasy':'mishaari_raashid_al_3afaasee','ar.abdulbasitmurattal':'abdul_basit_murattal','ar.husary':'mahmood_khaleel_al-husaree','ar.minshawi':'muhammad_siddeeq_al-minshaawee','ar.abdurrahmaansudais':'abdurrahmaan_as-sudays','yasser-surah':'yasser_ad-dussary'};
const chapterIds={'ar.alafasy':7,'ar.abdulbasitmurattal':2,'ar.husary':6,'ar.minshawi':9,'ar.abdurrahmaansudais':3,'yasser-surah':97};
const pad=n=>String(n).padStart(3,'0');let playToken=0;
function chosenSurah(){const n=Number($id('v19-surah-select')?.value||state.selected||0);return state.corpus?.surahs?.[n-1]}
function clearPlaying(){document.querySelectorAll('#verses .is-playing').forEach(x=>x.classList.remove('is-playing'))}
function markPlaying(n,scroll=true){clearPlaying();const card=$id(`ayet-${n}`);card?.classList.add('is-playing');if(scroll)card?.scrollIntoView({behavior:'smooth',block:'center'})}
async function getChapterAudio(reciter,surah,signal){const id=chapterIds[reciter]||7,response=await fetch(`https://api.quran.com/api/v4/chapter_recitations/${id}/${surah}?segments=true`,{signal});if(!response.ok)throw Error('Ses bilgisi alınamadı');const file=(await response.json()).audio_file;if(!file?.audio_url)throw Error('Ses adresi bulunamadı');return file}
async function playSurah(startAyah=1){
 const s=chosenSurah();if(!s)return;document.querySelector('.quran-setup')?.classList.remove('open');
 const reciter=$id('arabic-reciter')?.value||'ar.alafasy',own=++playToken;player.pause();player.removeAttribute('src');player.load();player.ontimeupdate=null;markPlaying(startAyah,false);setStatus?.(`${s.name} suresi hazırlanıyor…`);
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);let file;try{file=await getChapterAudio(reciter,s.number,controller.signal)}catch(_){setStatus?.('Ses bilgisi alınamadı. Bağlantıyı denetleyip yeniden deneyin.');return}finally{clearTimeout(timer)}
 const segments=file.timestamps||[];player.onended=()=>{if(own!==playToken)return;clearPlaying();setStatus?.(`${s.name} suresi tamamlandı.`)};player.onerror=()=>{if(own===playToken)setStatus?.('Ses kaydı açılamadı. İnternet bağlantısını denetleyin.')};player.src=file.audio_url;player.hidden=false;player.load();if(startAyah>1){const wanted=segments.find(x=>Number(x.verse_key?.split(':')[1])===Number(startAyah));if(wanted)player.currentTime=Math.max(0,wanted.timestamp_from/1000+.01)}
 try{await player.play();setStatus?.(`${s.name} Suresi ${startAyah}. ayetten kesintisiz oynatılıyor.`)}catch(_){setStatus?.('Ses başlatılamadı. Bağlantıyı denetleyip yeniden deneyin.');return}
 if(own!==playToken||!segments.length)return;let shown=0;player.ontimeupdate=()=>{if(own!==playToken)return;const ms=player.currentTime*1000,x=segments.find(v=>ms>=v.timestamp_from&&ms<v.timestamp_to),n=x?Number(x.verse_key.split(':')[1]):0;if(n&&n!==shown){shown=n;markPlaying(n,true)}};
}
window.playFullSurahFromAyah=playSurah;const playButton=$id('play-arabic');if(playButton)playButton.onclick=()=>playSurah(1);
const mealNames={'tr.yazir':'Elmalılı Hamdi Yazır','tr.ates':'Süleyman Ateş','tr.bulac':'Ali Bulaç','tr.yildirim':'Suat Yıldırım'},dayIndex=n=>Math.floor(new Date().setHours(0,0,0,0)/86400000)%n;
async function paintDailyWithWidgetMeal(){const panel=$id('daily-content'),active=document.querySelector('[data-day="ayet"].active');if(!panel||!active||!state.corpus?.surahs?.length)return;const prayers=bigDuas.filter(x=>x.surah),item=prayers[dayIndex(prayers.length)],surah=state.corpus.surahs[item.surah-1],ayah=surah?.ayahs[item.ayah-1];if(!ayah)return;const edition=localStorage.getItem('widgetMealEdition')||'tr.yazir',cacheKey=`daily-meal-${edition}-${ayah.global}`;let value=localStorage.getItem(cacheKey);if(!value){try{const response=await fetch(`https://api.alquran.cloud/v1/ayah/${ayah.global}/${edition}`);if(!response.ok)throw Error();value=(await response.json())?.data?.text;if(value)localStorage.setItem(cacheKey,value)}catch(_){value=ayah.tr}}panel.innerHTML='';const b=document.createElement('b'),h=document.createElement('h3'),p=document.createElement('p');b.textContent='Günün ayeti';h.textContent=value||ayah.tr;p.textContent=`${surah.name} Suresi, ${item.ayah}. ayet · ${mealNames[edition]||'Seçilen meal'}`;panel.append(b,h,p)}
document.addEventListener('click',event=>{if(event.target.closest('[data-day="ayet"]'))setTimeout(paintDailyWithWidgetMeal,0)});document.addEventListener('change',event=>{if(event.target.id==='widget-meal')setTimeout(paintDailyWithWidgetMeal,0)});const dailyWait=setInterval(()=>{if(state.corpus?.surahs?.length){clearInterval(dailyWait);setTimeout(paintDailyWithWidgetMeal,450)}},150);setTimeout(()=>clearInterval(dailyWait),20000);
})();
